 [Test,Explicit("Frozen 94349cf bulk API; local memory policies only.")]
 public async Task ActualBulkNativeSelectionLostReplyAndFiftyMemberContinuation(){
  var(wire,session)=await Setup();Func<string,Task<RunApiHttpResponse>> control=path=>wire.SendAsync(GameApiBearerAuthRequestFactory.WithBearerToken(new RunApiHttpRequest("POST","/__fixture/"+path,null,null),session.AccessToken));var journal=new Journal();using var state=new AccountScreenRuntime(wire,journal,()=>session,()=>1);await control("shop-enable");await control("recurring-enable");await state.EnterRecurringAsync();await control("recurring-finishes");await state.SyncRecurringAsync();await state.RefreshSharedAsync();
  var root=new GameObject("BulkHttpUi",typeof(RectTransform));((RectTransform)root.transform).sizeDelta=new Vector2(720,1280);var safe=new GameObject("SafeArea",typeof(RectTransform));safe.transform.SetParent(root.transform,false);var rect=(RectTransform)safe.transform;rect.anchorMin=Vector2.zero;rect.anchorMax=Vector2.one;rect.sizeDelta=Vector2.zero;
  try{var deck=LobbyCommandDeck.Attach(root,UnityEditor.AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/_LASTRAIL/UI/StartupResources/BootstrapFont.asset"),"LOCAL HTTP",1,new MissionShellMissionRowState[0],null,null);deck.BindAccount(state);deck.OpenPage(LobbyPage.Missions);while(state.Busy||state.RecurringLoading)await Task.Yield();root.GetComponentsInChildren<Button>().Single(b=>b.name=="BulkQuests").onClick.Invoke();Assert.That(root.GetComponentsInChildren<Button>().Single(b=>b.name=="BulkConfirm").interactable,Is.False);root.GetComponentsInChildren<Button>().Single(b=>b.name=="BulkSelectAll").onClick.Invoke();Assert.That(root.GetComponentsInChildren<Button>().Single(b=>b.name=="BulkConfirm").interactable,Is.True);typeof(AccountScreenIntegrationTests).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{root,"bulk-selection-pinned-local-http.png"});
   wire.LoseDeparture="/v1/recurring/bulk-claims";root.GetComponentsInChildren<Button>().Single(b=>b.name=="BulkConfirm").onClick.Invoke();while(state.Busy||state.RecurringLoading)await Task.Yield();var action=state.Pending;Assert.That(action?.Kind,Is.EqualTo("recurring-bulk"));Assert.That(state.LastBulkResult,Is.Null);root.GetComponentsInChildren<Button>().Single(b=>b.name=="BulkContinue").onClick.Invoke();while(state.Busy||state.RecurringLoading)await Task.Yield();Assert.That(state.Pending,Is.Null,state.BulkNotice);Assert.That(state.LastBulkResult.Success,Is.EqualTo(2));var calls=wire.Requests.Where(r=>r.EndpointPath=="/v1/recurring/bulk-claims").ToArray();Assert.That(calls.Length,Is.EqualTo(2));Assert.That(calls.All(r=>Key(r)==action.Key&&r.BodyJson==action.Payload),Is.True);typeof(AccountScreenIntegrationTests).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{root,"bulk-result-pinned-local-http.png"});deck.CloseDialog();
   // A previously persisted explicit 50-level request includes levels that are still unearned.
   var body=new JObject{["kind"]="PASS_LEVEL",["policyId"]="fixture-pass",["track"]="FREE",["levels"]=new JArray(Enumerable.Range(1,50))}.ToString();var saved=new PendingAccountAction("account_test","recurring-bulk","bulk",0,"fixture_fifty",body);journal.Save(saved);
   // SynchronizeSession does not re-read same-owner journals; recover through a new runtime, as on app restart.
   using var resumed=new AccountScreenRuntime(wire,journal,()=>session,()=>1);await resumed.RetryPendingAsync();Assert.That(resumed.LastBulkResult,Is.Not.Null,resumed.BulkNotice);Assert.That(resumed.LastBulkResult.Total,Is.EqualTo(50));Assert.That(resumed.LastBulkResult.Pending,Is.GreaterThanOrEqualTo(40));var first=resumed.LastBulkResult.Items;var hash=(await control("lookup-digest")).BodyJson;var posts=wire.Requests.Count(r=>r.Method=="POST"&&r.EndpointPath=="/v1/recurring/bulk-claims");await resumed.RefreshBulkResultAsync();Assert.That((await control("lookup-digest")).BodyJson,Is.EqualTo(hash));Assert.That(wire.Requests.Count(r=>r.Method=="POST"&&r.EndpointPath=="/v1/recurring/bulk-claims"),Is.EqualTo(posts));
   for(int n=0;n<10&&resumed.Pending!=null;n++){int prior=resumed.LastBulkResult.Pending;await resumed.ContinueBulkAsync();Assert.That(prior-resumed.LastBulkResult.Pending,Is.InRange(0,10));}Assert.That(resumed.Pending,Is.Null,resumed.BulkNotice);Assert.That(resumed.LastBulkResult.Success,Is.EqualTo(2));Assert.That(resumed.LastBulkResult.Failed,Is.EqualTo(48));foreach(JObject item in first.Where(i=>(string)i["status"]!="RETRY_PENDING"))Assert.That(JToken.DeepEquals(item,resumed.LastBulkResult.Items[(int)item["index"]]),Is.True);Assert.That(wire.Requests.Where(r=>r.EndpointPath=="/v1/recurring/bulk-claims"&&Key(r)==saved.Key).All(r=>r.BodyJson==body),Is.True);
   deck.BindAccount(resumed);deck.OpenBulkResults();typeof(AccountScreenIntegrationTests).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{root,"bulk-partial-failure-pinned-local-http.png"});
  }finally{UnityEngine.Object.DestroyImmediate(root);}
 }
 [Test,Explicit("Frozen 94349cf actual mail expiry and individual/bulk shared rights.")]
 public async Task ActualBulkMailSelectionExpiryAndIndividualReceiptRace(){
  var(wire,session)=await Setup();Func<string,Task<RunApiHttpResponse>> control=path=>wire.SendAsync(GameApiBearerAuthRequestFactory.WithBearerToken(new RunApiHttpRequest("POST","/__fixture/"+path,null,null),session.AccessToken));using var state=new AccountScreenRuntime(wire,new Journal(),()=>session,()=>1);await control("shop-enable");await control("recurring-enable");await control("recurring-old-finishes");await state.SyncRecurringAsync();await control("recurring-send-mail");await state.RefreshRecurringAsync();var selection=state.PrepareBulkSelection("MAIL");Assert.That(selection.Rows.Count,Is.EqualTo(2));var ids=selection.Rows.Select(r=>(string)r["id"]).ToArray();var command=state.PrepareBulkCommand(selection,ids);Assert.That(command,Is.Not.Null);Assert.That(state.PrepareBulkCommand(selection,new[]{ids[0],ids[0]}),Is.Null);Assert.That(state.PrepareBulkCommand(selection,new[]{"not_selected"}),Is.Null);
  await state.ClaimRecurringAsync("recurring-mail",ids[0]);var receipt=state.LastRecurringGrant;Assert.That(receipt,Is.Not.Null);await control("recurring-expire-mail");await state.SubmitBulkAsync(command);Assert.That(state.Pending,Is.Null,state.BulkNotice);var result=state.LastBulkResult;Assert.That(result,Is.Not.Null,state.BulkNotice);Assert.That(result.Complete,Is.True);Assert.That(result.Success,Is.EqualTo(1));Assert.That(result.Failed,Is.EqualTo(1));Assert.That((string)result.Items[0]["status"],Is.EqualTo("REPLAYED"));Assert.That(JToken.DeepEquals(result.Items[0]["receipt"],receipt),Is.True);Assert.That((string)result.Items[1]["errorCode"],Is.EqualTo("quest_mail_expired"));Assert.That((int)JObject.Parse((await control("recurring-metrics")).BodyJson)["grants"],Is.EqualTo(1));var before=result.Items.ToString();await state.RefreshBulkResultAsync();Assert.That(state.LastBulkResult.Items.ToString(),Is.EqualTo(before));Assert.That(state.PrepareBulkSelection("MAIL").Rows.Count,Is.Zero);
 }
